import numpy as np

_SEED = 42
_N = 6000
_U = np.random.default_rng(_SEED).uniform(1e-12, 1.0, _N)


def _rate(x):
    return 2.5 - 1.0 * float(x)


def program(x) -> float:
    lam = _rate(x)
    samples = -np.log(_U) * (1.0 / lam)
    return float(np.mean(samples))

import numpy as np

_SAMPLE_COUNT = 30


def _uniforms():
    return np.random.default_rng(42).uniform(1e-12, 1.0, _SAMPLE_COUNT)


_U = _uniforms()


def program(x) -> float:
    x = float(x)
    lam = 2.5 - 2.0 * x
    return float(np.mean(-np.log(_U) / lam))

import numpy as np

_SEED = 42
_N = 6000
_U = np.random.default_rng(_SEED).uniform(1e-12, 1.0, _N)


def _draws(lam):
    return np.log(_U) / lam


def program(x) -> float:
    x = float(x)
    lam = 2.5 - 2.0 * x
    return float(np.mean(_draws(lam)))
